import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  // Form for adding/editing
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});

  // All courses (for dropdown in assignments/announcements)
  const [courses, setCourses] = useState([]);

  // Enrolled course IDs (for filtering student views)
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);

  // Assignment submission (text-based)
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');

  // View submission modal
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);

  // Grade assignment modal (instructor)
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');

  // Delete confirmation
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');

  // Other modals
  const [showStudentsModal, setShowStudentsModal] = useState(false);
  const [selectedCourseStudents, setSelectedCourseStudents] = useState([]);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);
    setGradeValue('');
    setFeedbackText('');
  };

  const load = async (endpoint) => {
    if (!endpoint) return [];
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetched = res.data;

      if (endpoint.includes('courses')) {
        fetched = fetched.map(course => ({
          ...course,
          students: Array.isArray(course.students) ? course.students.map(Number) : []
        }));
        setCourses(fetched);
      }

      return fetched;
    } catch (err) {
      console.error(err);
      return [];
    } finally {
      setLoading(false);
    }
  };

  const goTo = async (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData({});
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);

    const endpoint = getEndpoint(newPage);
    if (endpoint) {
      let fetched = await load(endpoint);
      setData(fetched);

      if (user?.role === 'student') {
        if (newPage === 'assignments' || newPage === 'announcements') {
          const filtered = fetched.filter(item => enrolledCourseIds.includes(item.courseid));
          setData(filtered);
        }
      }
    }
  };

  useEffect(() => {
    if (user) {
      load('courses').then(fetchedCourses => {
        const enrolledIds = fetchedCourses
          .filter(c => (c.students || []).includes(user.id))
          .map(c => c.id);
        setEnrolledCourseIds(enrolledIds);
      });

      goTo('courses');
    }
  }, [user]);

  useEffect(() => {
    if (user && page !== 'login' && page !== 'courses') {
      goTo(page);
    }
  }, [page, user]);

  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => [...prev, courseId]);
      alert('Enrolled successfully!');
    } catch (err) {
      alert('Already enrolled or error');
    }
  };

  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => prev.filter(id => id !== courseId));
      alert('Dropped successfully!');
    } catch (err) {
      alert('Error dropping course');
    }
  };

  const submitAssignment = async (assignmentId) => {
    if (!submissionText.trim()) {
      alert('Please write your answer before submitting.');
      return;
    }
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: assignmentId,
        studentid: user.id,
        fileurl: submissionText
      });
      alert('Assignment submitted successfully!');
      setSubmissionText('');
      setSelectedAssignment(null);
      if (page === 'submissions') goTo('submissions');
    } catch (err) {
      alert('Submission failed');
    }
  };

  const viewSubmission = (text, submissionId) => {
    if (text && text.trim()) {
      setCurrentSubmissionText(text.trim());
      setCurrentSubmissionId(submissionId);
      setShowFileModal(true);
    } else {
      alert('No submission yet.');
    }
  };

  const requestDeleteSubmission = (submissionId) => {
    setItemToDelete(submissionId);
    setDeleteBase('submissions');
    setShowConfirmDelete(true);
  };

  // New: Instructor grades submission
  const gradeSubmission = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const saveGrade = async () => {
    if (!gradeValue || isNaN(gradeValue) || parseInt(gradeValue) < 0 || parseInt(gradeValue) > 100) {
      alert('Please enter a valid grade (0-100)');
      return;
    }

    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: parseInt(gradeValue),
        feedback: feedbackText
      });
      alert('Grade saved successfully!');
      setShowGradeModal(false);
      setGradeValue('');
      setFeedbackText('');
      setSubmissionToGrade(null);
      await goTo('submissions'); // Refresh submissions list
    } catch (err) {
      alert('Failed to save grade');
    }
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete}`);
      alert('Deleted successfully');
      setShowConfirmDelete(false);
      setItemToDelete(null);
      setDeleteBase('');
      setCurrentSubmissionId(null);
      setShowFileModal(false);
      await goTo(page);
    } catch (err) {
      alert('Delete failed');
    }
  };

  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  const openDeleteConfirm = (id, base) => {
    setItemToDelete(id);
    setDeleteBase(base);
    setShowConfirmDelete(true);
  };

  const saveItem = async (e) => {
    e.preventDefault();
    const base = page === 'students' ? 'users' : page;
    let payload = { ...formData };

    if (page === 'courses') payload.instructorid = user.id;
    if (page === 'students') payload.role = 'student';

    if ((page === 'announcements' || page === 'assignments') && !payload.courseid) {
      alert('Please select a valid course.');
      return;
    }

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created!');
      }
      setShowForm(false);
      await goTo(page);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.error || 'Invalid data'));
    }
  };

  const viewEnrolledStudents = (course) => {
    const students = (course.students || []).map(id => ({
      id,
      name: `Student ${id}`,
      email: `student${id}@example.com`
    }));
    setSelectedCourseStudents(students);
    setShowStudentsModal(true);
  };

  return (
    <div className="app">
      {page === 'login' && !user && (
        <div className="container">
          <h1>NM Student Portal</h1>
          <form onSubmit={login}>
            <input
              type="email"
              placeholder="Enter your email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              required
              style={{ width: '100%', padding: '10px', margin: '10px 0' }}
            />
            <button type="submit" className="btn">Login</button>
          </form>
        </div>
      )}

      {user && (
        <>
          <nav>
            <button onClick={() => goTo('courses')} className="btn">Courses</button>
            {user.role === 'student' && (
              <>
                <button onClick={() => goTo('assignments')} className="btn">Assignments</button>
                <button onClick={() => goTo('announcements')} className="btn">Announcements</button>
                <button onClick={() => goTo('submissions')} className="btn">My Submissions</button>
              </>
            )}
            {user.role === 'instructor' && (
              <>
                <button onClick={() => goTo('assignments')} className="btn">Assignments</button>
                <button onClick={() => goTo('announcements')} className="btn">Announcements</button>
                <button onClick={() => goTo('submissions')} className="btn">Grade Submissions</button>
                <button onClick={() => goTo('students')} className="btn">Students</button>
              </>
            )}
            <button onClick={logout} className="btn" style={{ background: '#e74c3c' }}>Logout</button>
          </nav>

          <div className="container">
            <h1>Welcome, {user.name} ({user.role})</h1>
            <h2>{page.charAt(0).toUpperCase() + page.slice(1)}</h2>

            {user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page) && (
              <button onClick={startAdd} className="btn" style={{ marginBottom: '20px' }}>
                + Add New {page.slice(0, -1)}
              </button>
            )}

            {loading && <p>Loading...</p>}

            {!loading && data.length === 0 && page !== 'courses' && (
              <p>No {page} available.</p>
            )}

            {data.length > 0 && (
              <table>
                <thead>
                  <tr>
                    <th>ID</th>
                    {page === 'courses' && <th>Title</th>}
                    {page === 'courses' && <th>Description</th>}
                    {page === 'courses' && <th>Syllabus</th>}
                    {page === 'courses' && user.role === 'instructor' && <th>Enrolled</th>}
                    {page === 'courses' && <th>Action</th>}

                    {(page === 'assignments' || page === 'announcements') && <th>Title</th>}
                    {page === 'assignments' && <th>Due Date</th>}
                    {page === 'assignments' && <th>Description</th>}
                    {(page === 'assignments' || page === 'announcements') && <th>Course ID</th>}
                    {(page === 'assignments' || page === 'announcements') && user.role === 'instructor' && <th>Actions</th>}

                    {page === 'submissions' && user.role === 'student' && <th>Assignment ID</th>}
                    {page === 'submissions' && user.role === 'student' && <th>Submission</th>}
                    {page === 'submissions' && user.role === 'student' && <th>Actions</th>}
                    {page === 'submissions' && user.role === 'student' && <th>Grade</th>}

                    {page === 'submissions' && user.role === 'instructor' && <th>Student ID</th>}
                    {page === 'submissions' && user.role === 'instructor' && <th>Assignment ID</th>}
                    {page === 'submissions' && user.role === 'instructor' && <th>Submission</th>}
                    {page === 'submissions' && user.role === 'instructor' && <th>Current Grade</th>}
                    {page === 'submissions' && user.role === 'instructor' && <th>Actions</th>}

                    {page === 'students' && <th>Name</th>}
                    {page === 'students' && <th>Email</th>}
                    {page === 'students' && <th>Actions</th>}
                  </tr>
                </thead>
                <tbody>
                  {data.map(item => (
                    <tr key={item.id}>
                      <td>{item.id}</td>

                      {page === 'courses' && <td>{item.title}</td>}
                      {page === 'courses' && <td>{item.description}</td>}
                      {page === 'courses' && <td>{item.syllabus || '—'}</td>}
                      {page === 'courses' && user.role === 'instructor' && <td>{(item.students || []).length}</td>}
                      {page === 'courses' && (
                        <td>
                          {user.role === 'instructor' && (
                            <>
                              <button onClick={() => startEdit(item)} className="btn">Edit</button>
                              <button onClick={() => openDeleteConfirm(item.id, 'courses')} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                            </>
                          )}
                          {user.role === 'student' && (
                            <button
                              onClick={() => (item.students || []).includes(user.id) ? drop(item.id) : enroll(item.id)}
                              className="btn"
                              style={{ background: (item.students || []).includes(user.id) ? '#e67e22' : '#4facfe' }}
                            >
                              {(item.students || []).includes(user.id) ? 'Drop' : 'Enroll'}
                            </button>
                          )}
                        </td>
                      )}

                      {(page === 'assignments' || page === 'announcements') && <td>{item.title}</td>}
                      {page === 'assignments' && <td>{item.duedate || 'No due date'}</td>}
                      {page === 'assignments' && <td>{item.description || '—'}</td>}
                      {(page === 'assignments' || page === 'announcements') && <td>{item.courseid}</td>}
                      {(page === 'assignments' || page === 'announcements') && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => openDeleteConfirm(item.id, page === 'assignments' ? 'assignments' : 'announcements')} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}

                      {page === 'assignments' && user.role === 'student' && (
                        <td>
                          <button onClick={() => setSelectedAssignment(item)} className="btn">Submit</button>
                        </td>
                      )}

                      {/* Student view of submissions */}
                      {page === 'submissions' && user.role === 'student' && <td>{item.assignmentid}</td>}
                      {page === 'submissions' && user.role === 'student' && (
                        <td>
                          {item.fileurl ? (
                            <button onClick={() => viewSubmission(item.fileurl, item.id)} className="btn">View Answer</button>
                          ) : 'No submission'}
                        </td>
                      )}
                      {page === 'submissions' && user.role === 'student' && item.fileurl && (
                        <td>
                          <button onClick={() => requestDeleteSubmission(item.id)} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}
                      {page === 'submissions' && user.role === 'student' && <td>{item.grade !== null ? `${item.grade}/100` : 'Not graded'}</td>}

                      {/* Instructor view of submissions */}
                      {page === 'submissions' && user.role === 'instructor' && <td>{item.studentid}</td>}
                      {page === 'submissions' && user.role === 'instructor' && <td>{item.assignmentid}</td>}
                      {page === 'submissions' && user.role === 'instructor' && (
                        <td>
                          {item.fileurl ? (
                            <button onClick={() => viewSubmission(item.fileurl, item.id)} className="btn">View Answer</button>
                          ) : 'No submission'}
                        </td>
                      )}
                      {page === 'submissions' && user.role === 'instructor' && <td>{item.grade !== null ? `${item.grade}/100` : 'Not graded'}</td>}
                      {page === 'submissions' && user.role === 'instructor' && (
                        <td>
                          {item.grade === null ? (
                            <button onClick={() => gradeSubmission(item)} className="btn">Grade</button>
                          ) : (
                            <button onClick={() => gradeSubmission(item)} className="btn" style={{ background: '#e67e22' }}>Regrade</button>
                          )}
                        </td>
                      )}

                      {page === 'students' && <td>{item.name}</td>}
                      {page === 'students' && <td>{item.email}</td>}
                      {page === 'students' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => openDeleteConfirm(item.id, 'users')} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            )}

            {/* Assignment Submission Modal (Student) */}
            {selectedAssignment && user.role === 'student' && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '600px', maxHeight: '90vh', overflowY: 'auto' }}>
                  <h3>Submit Assignment: {selectedAssignment.title}</h3>
                  <p><strong>Due:</strong> {selectedAssignment.duedate || 'No due date'}</p>
                  <p><strong>Description:</strong> {selectedAssignment.description || '—'}</p>
                  <label style={{ display: 'block', marginTop: '15px' }}>Your Answer:</label>
                  <textarea
                    value={submissionText}
                    onChange={(e) => setSubmissionText(e.target.value)}
                    placeholder="Write your answer here..."
                    rows="12"
                    style={{ width: '100%', padding: '12px', margin: '10px 0', fontFamily: 'Arial, sans-serif', fontSize: '14px' }}
                    required
                  />
                  <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                    <button onClick={() => submitAssignment(selectedAssignment.id)} className="btn">Submit Assignment</button>
                    <button onClick={() => { setSelectedAssignment(null); setSubmissionText(''); }} className="btn" style={{ background: '#e74c3c' }}>Cancel</button>
                  </div>
                </div>
              </div>
            )}

            {/* View Submission Modal */}
            {showFileModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '700px', maxHeight: '90vh', overflowY: 'auto' }}>
                  <h3>{user.role === 'instructor' ? 'Student Submission' : 'Your Answer'}</h3>
                  <div style={{ background: '#f9f9f9', padding: '20px', borderRadius: '8px', whiteSpace: 'pre-wrap', fontSize: '1.1em', minHeight: '100px' }}>
                    {currentSubmissionText || 'No content'}
                  </div>
                  {user.role === 'student' && currentSubmissionId && (
                    <div style={{ marginTop: '20px' }}>
                      <button
                        onClick={() => requestDeleteSubmission(currentSubmissionId)}
                        className="btn"
                        style={{ background: '#e74c3c' }}
                      >
                        Delete This Submission
                      </button>
                    </div>
                  )}
                  <button onClick={() => { setShowFileModal(false); setCurrentSubmissionText(''); setCurrentSubmissionId(null); }} className="btn" style={{ marginTop: '10px' }}>Close</button>
                </div>
              </div>
            )}

            {/* Grade Assignment Modal (Instructor) */}
            {showGradeModal && submissionToGrade && user.role === 'instructor' && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '700px', maxHeight: '90vh', overflowY: 'auto' }}>
                  <h3>Grade Assignment</h3>
                  <p><strong>Student:</strong> Student {submissionToGrade.studentid}</p>
                  <p><strong>Assignment:</strong> #{submissionToGrade.assignmentid}</p>

                  <div style={{ background: '#f9f9f9', padding: '20px', borderRadius: '8px', whiteSpace: 'pre-wrap', fontSize: '1.1em', minHeight: '120px', marginBottom: '20px' }}>
                    <strong>Student Answer:</strong><br/><br/>
                    {submissionToGrade.fileurl || 'No submission'}
                  </div>

                  <div className="form-group">
                    <label>Grade (0-100):</label>
                    <input
                      type="number"
                      min="0"
                      max="100"
                      value={gradeValue}
                      onChange={(e) => setGradeValue(e.target.value)}
                      placeholder="Enter grade"
                      style={{ width: '100%', padding: '10px', margin: '10px 0' }}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Feedback:</label>
                    <textarea
                      value={feedbackText}
                      onChange={(e) => setFeedbackText(e.target.value)}
                      placeholder="Optional feedback for student..."
                      rows="4"
                      style={{ width: '100%', padding: '10px', margin: '10px 0', fontFamily: 'Arial, sans-serif' }}
                    />
                  </div>

                  <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                    <button onClick={saveGrade} className="btn" style={{ background: '#27ae60' }}>Save Grade</button>
                    <button onClick={() => { setShowGradeModal(false); setGradeValue(''); setFeedbackText(''); setSubmissionToGrade(null); }} className="btn" style={{ background: '#e74c3c' }}>Cancel</button>
                  </div>
                </div>
              </div>
            )}

            {/* Add/Edit Form Modal */}
            {showForm && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '500px', maxHeight: '90vh', overflowY: 'auto' }}>
                  <h3>{editingItem ? 'Edit' : 'Add'} {page.slice(0, -1)}</h3>
                  <form onSubmit={saveItem}>
                    {Object.keys(getEmptyForm(page)).map(key => (
                      <div key={key} style={{ marginBottom: '15px' }}>
                        <label>{key.charAt(0).toUpperCase() + key.slice(1)}:</label>
                        {['announcements', 'assignments'].includes(page) && key === 'courseid' ? (
                          <select
                            value={formData[key] || ''}
                            onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                            required
                            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
                          >
                            <option value="">Select course</option>
                            {courses.map(course => (
                              <option key={course.id} value={course.id}>
                                {course.id} - {course.title}
                              </option>
                            ))}
                          </select>
                        ) : (
                          <input
                            type={key === 'duedate' ? 'date' : 'text'}
                            value={formData[key] || ''}
                            onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
                            required
                          />
                        )}
                      </div>
                    ))}
                    <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                      <button type="submit" className="btn">Save</button>
                      <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#e74c3c' }}>Cancel</button>
                    </div>
                  </form>
                </div>
              </div>
            )}

            {/* Delete Confirmation */}
            {showConfirmDelete && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '10px', textAlign: 'center' }}>
                  <h3>Confirm Delete</h3>
                  <p>Are you sure you want to delete this permanently?</p>
                  <div style={{ display: 'flex', justifyContent: 'center', gap: '10px' }}>
                    <button onClick={confirmDelete} className="btn" style={{ background: '#e74c3c' }}>Yes</button>
                    <button onClick={() => setShowConfirmDelete(false)} className="btn">Cancel</button>
                  </div>
                </div>
              </div>
            )}

            {/* Enrolled Students Modal */}
            {showStudentsModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '10px', maxWidth: '500px' }}>
                  <h3>Enrolled Students</h3>
                  {selectedCourseStudents.length > 0 ? (
                    <ul style={{ listStyle: 'none', padding: 0 }}>
                      {selectedCourseStudents.map(s => (
                        <li key={s.id} style={{ padding: '8px 0', borderBottom: '1px solid #ddd' }}>
                          {s.name} ({s.email})
                        </li>
                      ))}
                    </ul>
                  ) : <p>No students enrolled.</p>}
                  <button onClick={() => setShowStudentsModal(false)} className="btn">Close</button>
                </div>
              </div>
            )}
          </div>
        </>
      )}

      <footer>
        <h3>NM Student Portal © 2025</h3>
        <p>Full Role-Based System • All Features Working</p>
      </footer>
    </div>
  );
}

export default App;
